solution.solution.cpp:
#include <cstdio>
#include <string>
#include <vector>

class History
{
public:
    explicit History(int capacity) : m_data(static_cast<std::size_t>(capacity < 1 ? 1 : capacity), 0.0f) {}

    void push(float value)
    {
        m_data[m_next] = value;
        m_next = (m_next + 1) % m_data.size();
        if (m_count < m_data.size()) ++m_count;
    }

    int count() const { return static_cast<int>(m_count); }
    int offset() const { return m_count < m_data.size() ? 0 : static_cast<int>(m_next); }
    float at(int i) const { return m_data[(static_cast<std::size_t>(offset()) + static_cast<std::size_t>(i)) % m_data.size()]; }

    float average() const
    {
        if (!m_count) return 0.0f;
        float total{ 0.0f };
        for (int i{ 0 }; i < count(); ++i) total += at(i);
        return total / static_cast<float>(m_count);
    }

    float maximum() const
    {
        if (!m_count) return 0.0f;
        float best{ at(0) };
        for (int i{ 1 }; i < count(); ++i) if (at(i) > best) best = at(i);
        return best;
    }

    std::string overlay() const
    {
        char buffer[64];
        std::snprintf(buffer, sizeof(buffer), "avg %.1f  max %.1f", average(), maximum());
        return buffer;
    }

private:
    std::vector<float> m_data;
    std::size_t m_next{ 0 };
    std::size_t m_count{ 0 };
};

float smooth(float previous, float value, float k) { return previous + (value - previous) * k; }

unitTests:
TEST("before it is full") { History h{ 4 }; h.push(1); h.push(2); CHECK_EQ(h.count(), 2); CHECK_EQ(h.offset(), 0); CHECK_NEAR(h.at(0), 1.0, 1e-6); CHECK_NEAR(h.at(1), 2.0, 1e-6); }
TEST("wrapped") { History h{ 3 }; for (int i = 1; i <= 5; ++i) h.push(static_cast<float>(i)); CHECK_EQ(h.count(), 3); CHECK_EQ(h.offset(), 2); CHECK_NEAR(h.at(0), 3.0, 1e-6); CHECK_NEAR(h.at(1), 4.0, 1e-6); CHECK_NEAR(h.at(2), 5.0, 1e-6); }
TEST("statistics") { History h{ 4 }; h.push(10); h.push(20); h.push(15); CHECK_NEAR(h.average(), 15.0, 1e-5); CHECK_NEAR(h.maximum(), 20.0, 1e-6); CHECK_EQ(h.overlay(), std::string("avg 15.0  max 20.0")); }
TEST("empty") { History h{ 4 }; CHECK_NEAR(h.average(), 0.0, 1e-9); CHECK_NEAR(h.maximum(), 0.0, 1e-9); CHECK_EQ(h.overlay(), std::string("avg 0.0  max 0.0")); }
TEST("old samples leave the statistics") { History h{ 2 }; h.push(100); h.push(1); h.push(3); CHECK_NEAR(h.maximum(), 3.0, 1e-6); CHECK_NEAR(h.average(), 2.0, 1e-6); }
TEST("smoothing") { CHECK_NEAR(smooth(10, 20, 0.1f), 11.0, 1e-5); CHECK_NEAR(smooth(10, 20, 1.0f), 20.0, 1e-5); CHECK_NEAR(smooth(10, 20, 0.0f), 10.0, 1e-5); }

